import{_ as a,o as e,c as o,a2 as d}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"MiniTavern での設定","description":"MiniTavern と Ollama、LM Studio、KoboldCPP、llama.cpp：設定 → モデル接続、OpenAI 互換 Base URL と測連。","frontmatter":{"title":"MiniTavern での設定","description":"MiniTavern と Ollama、LM Studio、KoboldCPP、llama.cpp：設定 → モデル接続、OpenAI 互換 Base URL と測連。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"MiniTavern での設定 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern と Ollama、LM Studio、KoboldCPP、llama.cpp：設定 → モデル接続、OpenAI 互換 Base URL と測連。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/connect-app/minitavern"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/connect-app/minitavern"}]]},"headers":[],"relativePath":"ja/connect-app/minitavern.md","filePath":"ja/connect-app/minitavern.md","lastUpdated":1787224147000}'),r={name:"ja/connect-app/minitavern.md"};function l(i,t,n,c,s,p){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="minitavern-での設定" tabindex="-1">MiniTavern での設定 <a class="header-anchor" href="#minitavern-での設定" aria-label="Permalink to &quot;MiniTavern での設定&quot;">​</a></h1><p>本文は App 内経路：<strong>設定 → モデル → モデル接続</strong>。</p><h2 id="接続の新規作成" tabindex="-1">接続の新規作成 <a class="header-anchor" href="#接続の新規作成" aria-label="Permalink to &quot;接続の新規作成&quot;">​</a></h2><ol><li>MiniTavern → 下部 <strong>設定</strong>。</li><li><strong>モデル</strong> → <strong>モデル接続</strong>。</li><li>右上 <strong>新規</strong>。</li><li><strong>モデルプラットフォーム</strong>で <strong>カスタム</strong>（OpenAI 互換／カスタム Base URL、現行バージョンの選択肢文案準拠）。</li><li>下表に従いツールごとに記入して保存；<strong>測連</strong>があれば先に測連してからデフォルトへ。</li></ol><h2 id="各ツールの例" tabindex="-1">各ツールの例 <a class="header-anchor" href="#各ツールの例" aria-label="Permalink to &quot;各ツールの例&quot;">​</a></h2><p><code>YOUR_PC_IP</code> を PC の LAN IP に（<code>localhost</code> は使わない）。</p><table tabindex="0"><thead><tr><th>ツール</th><th>Base URL 例</th><th>モデル名</th><th>API Key</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ja/ollama/lan">Ollama</a></td><td><code>http://YOUR_PC_IP:11434/v1</code></td><td><code>ollama list</code> の名称</td><td>空欄または <code>ollama</code></td></tr><tr><td><a href="/ultra_guides/ja/lmstudio/server">LM Studio</a></td><td><code>http://YOUR_PC_IP:1234/v1</code></td><td>Local Server の id</td><td>空欄可</td></tr><tr><td><a href="/ultra_guides/ja/koboldcpp/server">KoboldCPP</a></td><td><code>http://YOUR_PC_IP:5001/v1</code></td><td><code>/v1/models</code> の id</td><td>空欄可</td></tr><tr><td><a href="/ultra_guides/ja/llamacpp/server">llama.cpp</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>server が返す id</td><td>空欄可</td></tr><tr><td><a href="/ultra_guides/ja/localai/install">LocalAI</a></td><td><code>http://YOUR_PC_IP:8080/v1</code></td><td>LocalAI の設定名</td><td>認証の有無に従う</td></tr><tr><td><a href="/ultra_guides/ja/jan/install">Jan</a></td><td>アプリ API ページのアドレス</td><td>一覧の id</td><td>アプリ設定に従う</td></tr><tr><td><a href="/ultra_guides/ja/textgen/install">text-generation-webui</a></td><td><code>http://YOUR_PC_IP:ポート/v1</code></td><td>拡張が返す id</td><td>拡張設定に従う</td></tr></tbody></table><p>別名は自由、例 <code>家里の Ollama</code>、<code>書斎 Kobold</code>。</p><h2 id="デフォルトにして開聊" tabindex="-1">デフォルトにして開聊 <a class="header-anchor" href="#デフォルトにして開聊" aria-label="Permalink to &quot;デフォルトにして開聊&quot;">​</a></h2><ol><li>モデル接続一覧で <strong>デフォルト</strong> に設定。</li><li>キャラカードを取り込む／選び、チャットでメッセージを送る。</li><li>PC 側の対応ツールにリクエスト活動が出る；App 内でストリーミングまたは一括返信を受け取る。</li></ol><h2 id="セッション単位の上書き-任意" tabindex="-1">セッション単位の上書き（任意） <a class="header-anchor" href="#セッション単位の上書き-任意" aria-label="Permalink to &quot;セッション単位の上書き（任意）&quot;">​</a></h2><p>あるチャットだけ一時的にローカルモデルへ：チャット設定でグローバル既定のモデル接続／パラメータを上書き。</p><h2 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h2><ul><li>スマホに <strong><code>http://localhost:...</code></strong> または <strong><code>http://127.0.0.1:...</code></strong> を入れない。</li><li>URL 末尾は <code>/v1</code> 推奨、<code>/chat/completions</code> まで書かない。</li><li>PC のスリープ、蓋閉じ、ネットワーク切替で IP が変わることがある。</li><li>ポートは実際に開いたもの準拠、上表はよくある既定のみ。</li></ul><p>つながらないときは <a href="/ultra_guides/ja/troubleshoot">排錯対照表</a>。ツール選びは <a href="/ultra_guides/ja/local/tools">ツール一覧</a>。</p>',15)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
